import{_ as i,o as a,c as e,y as t}from"./chunks/framework.CNTkXYA8.js";const E=JSON.parse('{"title":"如何在Windows上配置sshd服务器","description":"","frontmatter":{"title":"如何在Windows上配置sshd服务器","date":"2024-11-13T07:59:45.000Z","tags":["windows","ssh"],"how-to":true},"headers":[],"relativePath":"blog/sshonwin.md","filePath":"source/_posts/sshonwin.md"}'),h={name:"blog/sshonwin.md"};function n(l,s,p,r,k,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<p>首先，<a href="https://learn.microsoft.com/zh-cn/windows-server/administration/OpenSSH/openssh-server-configuration" target="_blank" rel="noreferrer">正主链接</a>。</p><h1 id="step-1-获得sshd功能" tabindex="-1">Step 1 获得sshd功能 <a class="header-anchor" href="#step-1-获得sshd功能" aria-label="Permalink to &quot;Step 1 获得sshd功能&quot;">​</a></h1><p>打开windows的扩展和可选功能，下载并打开“OpenSSH”服务器功能。</p><h1 id="step-2-打开防火墙" tabindex="-1">Step 2 打开防火墙 <a class="header-anchor" href="#step-2-打开防火墙" aria-label="Permalink to &quot;Step 2 打开防火墙&quot;">​</a></h1><p>在PowerShell中输入</p><div class="language-PowerShell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-NetFirewallRule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name sshd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DisplayName </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;OpenSSH Server (sshd)&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Enabled True </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Direction Inbound </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Protocol TCP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action Allow </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LocalPort </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span></span></code></pre></div><p>来打开22或者任何一个你想要开放的端口。</p><h1 id="step-3-配置ssh-config" tabindex="-1">Step 3 配置ssh config <a class="header-anchor" href="#step-3-配置ssh-config" aria-label="Permalink to &quot;Step 3 配置ssh config&quot;">​</a></h1><p>打开 %programdata%\\ssh\\sshd_config，（注意不是C:\\Users\\.ssh，不是服务器的配置），自行配置sshd。此处可以修改AgentForward，X11Forward等等，还可以修改免密登陆。</p><h1 id="step-4-设置ps为默认终端" tabindex="-1">Step 4 设置PS为默认终端 <a class="header-anchor" href="#step-4-设置ps为默认终端" aria-label="Permalink to &quot;Step 4 设置PS为默认终端&quot;">​</a></h1><div class="language-PowerShell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ItemProperty</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HKLM:\\HKEY_LOCAL_MACHINE\\SOFTWARE\\OpenSSH&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DefaultShell&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> powershell.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).Source</span></span></code></pre></div><p>这样，外部机器连接进去就完全是PowerShell的形状了，简直和本地一摸一样。</p><h1 id="step-5-重启sshd服务" tabindex="-1">Step 5 重启sshd服务 <a class="header-anchor" href="#step-5-重启sshd服务" aria-label="Permalink to &quot;Step 5 重启sshd服务&quot;">​</a></h1><p>输入</p><div class="language-PowerShell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Stop sshd </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Start sshd</span></span></code></pre></div><p>或者直接重启，应用刚刚所做的修改。此时，若能通过网络访问机器的ip，便可以随时随地ssh啦。而且还可以直接用vscode remote连你的机器。</p>`,16)])])}const g=i(h,[["render",n]]);export{E as __pageData,g as default};
